        gr.addQuery("device_id", deviceId);
        gr.query();
        while (gr.next()) {
            gr.certificate_status = certObj.status || gr.certificate_status;
            gr.certificate_creation_time = certObj.createdDate || gr.certificate_creation_time;
            gr.certificate_name = certObj.name || gr.certificate_name;
            gr.serial_number = certObj.serialNumber || gr.serial_number;
            if (certObj.expiryDate) gr.expiry_date = new GlideDateTime(certObj.expiryDate);
            gr.device_status = "PROVISIONED";
            gr.update();
            logCertWF("Info", "Updated device data for device_id: " + deviceId);
        }
    }

    function generatePassword(len) {
        var sets = {
            upper: "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
            lower: "abcdefghijklmnopqrstuvwxyz",
            num: "0123456789",
            sym: "!@#$%^&*()-_=+[]{}|;:,.<>?"
        };
        var all = sets.upper + sets.lower + sets.num + sets.sym;
        var out = [
            sets.upper[Math.floor(Math.random() * sets.upper.length)],
            sets.lower[Math.floor(Math.random() * sets.lower.length)],
            sets.num[Math.floor(Math.random() * sets.num.length)],
            sets.sym[Math.floor(Math.random() * sets.sym.length)]
        ];
        while (out.length < len) {
            out.push(all[Math.floor(Math.random() * all.length)]);
        }
        return out.sort(() => 0.5 - Math.random()).join('');
    }

    // === Main Logic ===
    try {
        var ritmNumber = workflow.scratchpad.req_item_number;
        var endpoint = gs.getProperty("x_1784056_sixscape.End Point") || "";
        if (endpoint.endsWith("/")) endpoint = endpoint.slice(0, -1);
        var midServer = gs.getProperty("x_1784056_sixscape.Mid Server Name") || "";
        var keyManagerPin = gs.getProperty("x_1784056_sixscape.Key Manager Pin") || "";
        var deviceVar = current.variables.device;
        var deviceName = deviceVar.device_name.toString();
        var profileId = parseInt(current.variables.profile.profile_id, 10);
        var deviceSysId = deviceVar.toString();
        var ownerId = current.variables.profile.profile_group_id.toString();
        var hostname = current.variables.hostname.toString();
        var downloadOnly = false;
        var tokenObj, response, authToken, deviceId, payload, plainPassword, encoded;
        var certStatus = current.variables.certificate_status.toString();
        var expiryDate = current.variables.certificate_expiry.toString();
        var threshold = current.variables.profile.renewal_threshold.toString();

		// Check whether the certificate to be download or request a new one
        var expiry = new GlideDateTime(expiryDate);
        // Get current date/time
        var now = new GlideDateTime();
        // Clone 'now' (so as not to mutate it) and add days
        var future = new GlideDateTime();
        future.addDaysUTC(parseInt(threshold, 10)); // Use addDaysUTC for scoped app
        // Debug Info
        workflow.info('Now: ' + now.getDisplayValue());
        workflow.info('Future: ' + future.getDisplayValue());
        workflow.info('Expiry: ' + expiry.getDisplayValue());
        // Check: is expiry between now and future?
        if (expiry.after(future) && certStatus != "REVOKED") {
            logCertWF("Info", "Expiry is beyond threshold! Take action here.");
            downloadOnly = true;
        }

        logCertWF("Info", "[Sixscape] Starting certificate workflow for: " + deviceName);
        // 1. Get Token
        tokenObj = new GetToken();
        response = tokenObj.TestConnection();
        if (!response || response.length < 2 || response[0] !== 200)
            throw "Token retrieval failed!";
        authToken = "Bearer " + JSON.parse(response[1]).authToken;

        // 2. Device Creation
        if (deviceName == "Add New Application") {
			var digest = new GlideDigest();

