			var hash = digest.getSHA256Hex(ipPort);

			// Truncate if you want a shorter ID (e.g. 16 hex chars)
			var vendorValue = hash.substring(0, 16);
			workflow.info("vendorValue " + vendorValue);
            payload = {
                deviceOwnerId: ownerId,
                deviceName: current.variables.device_name.toString(),
                preapproved: true,
                attributes: [{
                        name: "Vendor Device Id",
                        value: vendorValue
                    },
                    {
                        name: "Hostname",
                        value: hostname
                    },
                    {
                        name: "Bind Address",
                        value: current.variables.bind_address.toString()
                    },
                    {
                        name: "Bind Port",
                        value: current.variables.bind_port.toString()
                    }
                ]
            };
            var deviceReq = new sn_ws.RESTMessageV2();
            setMID(deviceReq);
            deviceReq.setHttpMethod("post");
            setCommonHeaders(deviceReq, authToken);
            deviceReq.setEndpoint(endpoint + "/v1/device");
            deviceReq.setRequestBody(JSON.stringify(payload));
            var deviceResp = executeREST(deviceReq, "Device Creation");
            deviceId = deviceResp.deviceId;
            logCertWF("Info", "Created device: " + deviceResp.deviceName + " / deviceId: " + deviceId);

            var deviceGR = new GlideRecordSecure("x_1784056_sixscape_device");
            deviceGR.initialize();
            deviceGR.device_id = deviceResp.deviceId;
            deviceGR.device_name = deviceResp.deviceName;
            deviceGR.device_owner_id = deviceResp.deviceOwnerId;
            deviceGR.device_status = deviceResp.status;
            deviceGR.profile = current.variables.profile.sys_id;
            workflow.scratchpad.deviceName = deviceResp.deviceName;
            deviceGR.insert();
            logCertWF("Info", "Inserted device record for: " + deviceResp.deviceName);
        } else {
            hostname = current.variables.certificate_name.toString();
            deviceId = deviceVar.device_id.toString();
            workflow.scratchpad.deviceName = deviceVar.device_name.toString();
        }

        // --- Download Only Block ---
        if (downloadOnly && deviceName != "Add New Application") {
            var certificateName = current.variables.certificate_name.toString();
            var createdDate = current.variables.certificate_creation_time.toString();
            var encodedCertId = encodeURIComponent(certificateName + "|" + createdDate);
            logCertWF("Info", "Download-only: Fetching certificate " + certificateName + " for deviceId: " + deviceId);

            var getReq = new sn_ws.RESTMessageV2();
            setMID(getReq);
            getReq.setHttpMethod("get");
            setCommonHeaders(getReq, authToken);
            getReq.setEndpoint(endpoint + "/v1/certificate/" + encodedCertId);
            var certData = executeREST(getReq, "Certificate Download");
            updateDevice(deviceId, certData);

            var cleanContent = certData.content.replace(/\\r/g, "\r").replace(/\\n/g, "\n");
            if (!keyManagerPin) {
                attachToRITM(certificateName + ".cer", "application/x-x509-ca-cert", cleanContent);
                return "true";
            }
            // Recovery with PIN
            plainPassword = generatePassword(10);
            encoded = gs.base64Encode(plainPassword);
            payload = {
                pin: keyManagerPin,
                passphrase: encoded
            };
            var postReq = new sn_ws.RESTMessageV2();
            setMID(postReq);
            postReq.setHttpMethod("post");
            setCommonHeaders(postReq, authToken);
            postReq.setEndpoint(endpoint + "/v1/certificate/" + encodedCertId + "/recover");
            postReq.setRequestBody(JSON.stringify(payload));
            var certLocation = executeREST(postReq, "Certificate Download", true);
            logCertWF("Info", "Recovery requested for certificate: " + certificateName);

            // Wait loop (busy wait) for polling status
            var pollAttempts = 0,
                maxRetryCount = 30;
            while (pollAttempts <= maxRetryCount) {
                pollAttempts++;
                var pollGetReq = new sn_ws.RESTMessageV2();
                setMID(pollGetReq);
                pollGetReq.setHttpMethod("get");
                setCommonHeaders(pollGetReq, authToken);
                pollGetReq.setEndpoint(endpoint + certLocation);
                pollGetReq.setHttpTimeout(30000);
                var pollResponse = pollGetReq.execute();
                var status = pollResponse.getStatusCode();

                if (status !== 200 && status !== 404) {
                    logCertWF("Error", "Unexpected HTTP " + status + " during polling on attempt " + pollAttempts);
                    throw new Error("Unexpected response while polling for certificate: HTTP " + status);
                }
                if (status === 404) break;
                var pollBody, respBody = pollResponse.getBody();
                try {
                    pollBody = JSON.parse(respBody);
                } catch (e) {
                    logCertWF("Error", "Polling: failed to parse JSON on attempt " + pollAttempts + ". Response: " + respBody);
                    throw new Error("Polling: failed to parse response JSON.");
                }
                logCertWF("Info", "Polling attempt " + pollAttempts + " returned HTTP " + status + ": status = " + pollBody.status);

                if (pollBody.status == "COMPLETED_WITH_ERROR") {
                    current.comments = "Couldn't recover the certificate from the key manager. Attaching the certificate content.";
                    attachToRITM(certificateName + ".cer", "application/x-x509-ca-cert", cleanContent);
                    workflow.scratchpad.email_body = "Your certificate file (.cer) is attached and ready for download.";
                    logCertWF("Warning", "Polling returned COMPLETED_WITH_ERROR for " + certificateName + " on attempt " + pollAttempts + " - attached standard cert and email notice.");
                    return "true";
                }
                if (pollBody.status == "COMPLETED") break;
                if (pollBody.status == "Failed") {
                    logCertWF("Error", "Polling returned FAILED on attempt " + pollAttempts);
                    throw new Error("Couldn't retrieve the certificate archive.");
                }
                if (pollAttempts > maxRetryCount) {
                    logCertWF("Error", "Polling timed out after " + pollAttempts + " attempts.");
                    throw new Error("Polling timed out.");
                }
                // Wait - ~5 seconds
                var delay = 5 * 1000,
                    end = new Date().getTime() + delay;
                while (new Date().getTime() < end) {}
            }

            // Download and attach the P12 file
            var downloadReq = new sn_ws.RESTMessageV2();
            setMID(downloadReq);
            setCommonHeaders(downloadReq, authToken);
            downloadReq.setHttpMethod('get');
            downloadReq.setRequestHeader('Accept', '*/*');
            downloadReq.setEndpoint(endpoint + certLocation + ".p12");
            downloadReq.setHttpTimeout(30000);
            downloadReq.saveResponseBodyAsAttachment('sc_req_item', workflow.scratchpad.req_item_sys_id, certificateName + '.p12');
            response = downloadReq.execute();
            workflow.scratchpad.email_body = "Your P12 file is attached and its <b>Passphrase:</b> " + encoded;
            logCertWF("Info", "Attached P12 file (download only) for certificate " + certificateName);
            return "true";
        }

        // 3. Certificate Request
        var isUsingCSR = current.variables.csr.toString() !== "";
        if (!isUsingCSR) {
            plainPassword = generatePassword(10);
            encoded = gs.base64Encode(plainPassword);
            payload = {
                entityId: deviceId,
                profileId: profileId,
                passphrase: encoded
            };
            workflow.scratchpad.email_body = "Your P12 file is attached and its <b>Passphrase:</b> " + encoded;
            logCertWF("Info", "Submitting certificate request with P12 for device: " + deviceId);
        } else {
            var rawCSR = (current.variables.csr + "").replace(/\\r\\n/g, "\r\n");
            payload = {
                entityId: deviceId,
                profileId: profileId,
                csr: rawCSR
            };
            workflow.scratchpad.email_body = "Your certificate file (.cer) is attached and ready for download.";
            logCertWF("Info", "Submitting certificate request with CSR for device: " + deviceId);
        }

        var certReq = new sn_ws.RESTMessageV2();
        setMID(certReq);
        certReq.setHttpMethod("post");
        setCommonHeaders(certReq, authToken);
        certReq.setEndpoint(endpoint + "/v1/certificate");
        certReq.setRequestBody(JSON.stringify(payload));
        var certResp = executeREST(certReq, "Initiate Cert Request");

        // 4. Poll for CSR resourceUrl if needed
        if (isUsingCSR && certResp.csrName && certResp.csrCreationTime && !certResp.resourceUrl) {
            var retryCount = 0,
                maxRetries = 30;
            while (retryCount < maxRetries) {
                logCertWF("Info", "Polling for Certificate resource URL (attempt " + (retryCount + 1) + ")");
                payload = {
                    entityId: deviceId,
                    profileId: profileId,
                    csrName: certResp.csrName,
                    csrCreationTime: certResp.csrCreationTime
                };
                var retryReq = new sn_ws.RESTMessageV2();
                setMID(retryReq);
                retryReq.setHttpMethod("post");
                setCommonHeaders(retryReq, authToken);
                retryReq.setEndpoint(endpoint + "/v1/certificate");
                retryReq.setRequestBody(JSON.stringify(payload));
                certResp = executeREST(retryReq, "CSR Polling Cert Request");
                if (certResp.resourceUrl) break;
                retryCount++;
                // Wait 5s per retry
                var delay = 5 * 1000,
                    end = new Date().getTime() + delay;
                while (new Date().getTime() < end) {}
            }
            if (!certResp.resourceUrl) throw "CSR polling exceeded max retry count.";
        }

        // 5. Download Certificate (CSR scenario)
        if (isUsingCSR) {
            var encodedUrl = certResp.resourceUrl.split('/').map(encodeURIComponent).join('/');
            var csrGetReq = new sn_ws.RESTMessageV2();
            setMID(csrGetReq);
            csrGetReq.setHttpMethod("get");
            setCommonHeaders(csrGetReq, authToken);
            csrGetReq.setEndpoint(endpoint + "/" + encodedUrl);
            var certData = executeREST(csrGetReq, "Certificate Download");
            updateDevice(deviceId, certData);
            var cleanContent = certData.content.replace(/\\r/g, "\r").replace(/\\n/g, "\n");
            attachToRITM(hostname + ".cer", "application/x-x509-ca-cert", cleanContent);
            logCertWF("Info", "Attached .cer file (CSR) for device: " + deviceId);
        } else {
            attachToRITM(hostname + ".p12", "application/x-pkcs12", certResp.pkcs12);
            logCertWF("Info", "Attached .p12 file for device: " + deviceId);
        }

        // 6. Sync device info with latest certificate (if P12)
        if (!isUsingCSR) {
            var subfilter = "(name=eq " + deviceId + " $or owner=eq " + deviceId + " $or owner=eq " + ownerId + ")";
            var listReq = new sn_ws.RESTMessageV2();
            setMID(listReq);
            listReq.setHttpMethod("get");
            setCommonHeaders(listReq, authToken);
            listReq.setEndpoint(endpoint + "/v1/certificate");
            listReq.setQueryParameter("$subfilter", subfilter);
            listReq.setQueryParameter("$sort", "expiryDate desc");
            var certList = executeREST(listReq, "Get Certificate Details");
            if (Array.isArray(certList) && certList.length > 0) {
                updateDevice(deviceId, certList[0]);
                logCertWF("Info", "Device updated with latest certificate details for device: " + deviceId);
            }
        }

        logCertWF("Info", "[Sixscape] Certificate workflow completed.");
        return "true";

    } catch (err) {
        handleError(err, "Certificate Workflow");
        current.stage = "closed_incomplete";
        current.state = 4;
        var req = current.request && current.request.getRefRecord && current.request.getRefRecord();
        if (req) {
            req.state = 4;
            req.request_state = "closed_incomplete";
            req.update();
        }
        return "false";
    }
})();

