activity.result = (function() {

    // Local logging helper for your app log table
    function logWF(logLevel, message) {
        var gr = new GlideRecord('x_1784056_sixscape_log');
        gr.initialize();
        gr.script = "Set Scratchpad Values";
        gr.log_level = logLevel;
        gr.message = message;
        gr.application = "Sixscape IDC";
        gr.insert();

        // Also mirror to workflow log
        if (logLevel == "Info") workflow.info(message);
        else workflow.error(message);
    }

    try {
        // Get the associated request record
        var requestGR = current.request.getRefRecord();
        if (requestGR) {
            requestGR.short_description = 'IDcentral Certificate Request';
            requestGR.update();
        } else {
            logWF("Warning", "No request record found to update short_description.");
        }

        // Store the current request item sys_id in the workflow scratchpad
        workflow.scratchpad.req_item_sys_id = current.sys_id;
		workflow.scratchpad.req_item_number = current.number;
        logWF("Info", "Request Item Sys ID: " + current.sys_id);

        // Get the profile sys_id from variables
        var profileSysId = current.variables.profile;
        logWF("Info", "Profile Sys ID: " + profileSysId + " for the RITM: " + workflow.scratchpad.req_item_number);

        // Query the profile record
        var profileGR = new GlideRecord('x_1784056_sixscape_profile');
        if (profileGR.get(profileSysId)) {
            workflow.scratchpad.approval_enabled = profileGR.getValue('approval_enabled') || 'No';
            workflow.scratchpad.approval_group_id = profileGR.getValue('assignment_group');
            logWF("Info", "Profile found. Approval enabled: " + workflow.scratchpad.approval_enabled + 
                ", Approval group: " + workflow.scratchpad.approval_group_id);
        } else {
            workflow.scratchpad.approval_enabled = 'No';
            workflow.scratchpad.approval_group_id = '';
            logWF("Warning", "Profile not found for Sys ID: " + profileSysId + " for the RITM: " + workflow.scratchpad.req_item_number);
        }

        return "true";
    } catch (e) {
        // Set the request item to closed_incomplete
        current.stage = "closed_incomplete";
        current.state = 4;
        current.comments = "Failed while processing the certificate request.";

        // Set the parent request to closed_incomplete
        var req = current.request.getRefRecord();
        if (req) {
            req.state = 4;
            req.request_state = 'closed_incomplete';
            req.update();
        }
        logWF("Error", "RITM Number: " + workflow.scratchpad.req_item_number + ", error while processing the workflow: " + e);

        return "false";
    }
})();

